function getNestedProperties(path, options) {
    const [basePath] = path.split('.');

    // Check if there is no more path left
    if (!basePath || !options) {
        return {};
    }

    const currentKey = basePath.charAt(0);

    // Handle base case: when we reach the last part of the path
    if (currentKey === '') {
        return options;
    }

    // Recursively search for the property
    return Object.keys(options).reduce((acc, key) => {
        const newPath = `${key}.${basePath.slice(currentKey.length + 1)}`;

        if (options[key]) {
            acc[newPath] = options[key];
        } else {
            // If the property does not exist, continue with the rest of the path
            acc = { ...acc, ...getNestedProperties(newPath, options[key]) };
        }

        return acc;
    }, {});
